def get_mask_for_state(name: str) -> List[GridPoint]:
    return STATE_MASKS.get(name, [])


def get_state_at_cell(x: int, y: int) -> Optional[str]:
    for state_name, mask in STATE_MASKS.items():
        if (x, y) in mask:
            return state_name
    return None
